import 'package:flutter/material.dart'; import '../models/expense.dart'; import '../models/recurring_bill.dart'; import '../services/database_service.dart'; import '../services/notification_service.dart'; import '../services/preferences_service.dart'; import '../widgets/money.dart';
class TrackerScreen extends StatefulWidget { const TrackerScreen({super.key,required this.prefs}); final PreferencesService prefs; @override State<TrackerScreen> createState()=>_TrackerScreenState(); }
class _TrackerScreenState extends State<TrackerScreen>{ List<Expense> items=[]; @override void initState(){super.initState();load();} Future<void> load()async{items=await DatabaseService.instance.monthExpenses(DateTime.now());if(mounted)setState((){});} double get total=>items.fold(0,(a,b)=>a+b.amount); Future<void> add()async{final a=TextEditingController(),note=TextEditingController();String cat='Groceries'; final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('Add expense'),content:StatefulBuilder(builder:(c,set)=>SingleChildScrollView(child:Column(children:[TextField(controller:a,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Amount')),DropdownButtonFormField(value:cat,items:['Rent','EMI','Groceries','Utilities','Transport','Entertainment','Subscriptions','Other'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>set(()=>cat=v!),decoration:const InputDecoration(labelText:'Category')),TextField(controller:note,decoration:const InputDecoration(labelText:'Note'))])),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))]));if(ok==true&&double.tryParse(a.text)!=null){await DatabaseService.instance.addExpense(Expense(amount:double.parse(a.text),category:cat,date:DateTime.now(),note:note.text));await load();}}
 Future<void> budget()async{final c=TextEditingController(text:widget.prefs.budget.toStringAsFixed(0));if(await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('Monthly budget'),content:TextField(controller:c,keyboardType:TextInputType.number,decoration:const InputDecoration(prefixText:'₹')),actions:[FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Save'))]))==true){final v=double.tryParse(c.text);if(v!=null){await widget.prefs.setBudget(v);setState((){});}}}
 Future<void> bills()async{final n=TextEditingController(),a=TextEditingController(),d=TextEditingController(text:'2');if(await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('Recurring bill'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Name')),TextField(controller:a,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Amount')),TextField(controller:d,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Reminder days before due date'))]),actions:[FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Save'))]))==true&&double.tryParse(a.text)!=null){final b=RecurringBill(name:n.text,amount:double.parse(a.text),category:'Other',dueDay:5,reminderDays:int.tryParse(d.text)??2);final id=await DatabaseService.instance.addBill(b);await NotificationService.instance.schedule(RecurringBill(id:id,name:b.name,amount:b.amount,category:b.category,dueDay:b.dueDay,reminderDays:b.reminderDays));if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Bill reminder scheduled monthly')));}}
 @override Widget build(BuildContext c){final b=widget.prefs.budget;final pct=b>0?total/b:0;return ListView(padding:const EdgeInsets.all(16),children:[Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text('Monthly overview',style:Theme.of(c).textTheme.headlineSmall),IconButton(onPressed:budget,icon:const Icon(Icons.account_balance))]),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Total spent'),MoneyText(total,style:const TextStyle(fontSize:28,fontWeight:FontWeight.bold)),if(b>0)LinearProgressIndicator(value:pct.clamp(0,1),color:pct>.9?Colors.red:null),if(b>0)Text('${money(total)} of ${money(b)} budget') ])),const SizedBox(height:12),FilledButton.icon(onPressed:add,icon:const Icon(Icons.add),label:const Text('Add Expense')),OutlinedButton.icon(onPressed:bills,icon:const Icon(Icons.notifications),label:const Text('Recurring Bills & Reminders')),const SizedBox(height:8),...items.map((e)=>Dismissible(key:ValueKey(e.id),onDismissed:(_){if(e.id!=null)DatabaseService.instance.deleteExpense(e.id!);setState(()=>items.remove(e));},child:ListTile(title:Text(e.category),subtitle:Text(e.note??''),trailing:MoneyText(e.amount))))]);}
}
